insert into public.topik_sources(source_key, title, edition, scope, notes) values ('TOPIK_3_4_PHUONG_ANH_READING_20_21', 'Chinh phục TOPIK 3-4 – Tiếng Hàn Phương Anh', 'TOPIK 3-4. B11(2).pdf', 'TOPIK II Reading 20-21', 'Sách tổ chức theo cặp 19–20 và 21–22. Dataset tập trung kỹ năng câu 20 (chủ đề/nội dung trọng tâm) và câu 21 (관용 표현), đồng thời giữ câu 19/22 đi kèm để bảo toàn ngữ cảnh bài gốc.') on conflict (source_key) do update set title = excluded.title, edition = excluded.edition, scope = excluded.scope, notes = excluded.notes;
